package com.dhegeniusmedia.sms;
import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.os.Bundle;import android.telephony.SmsMessage;import org.json.JSONObject;
public class SmsReceiver extends BroadcastReceiver{public void onReceive(Context context,Intent intent){if(!"android.provider.Telephony.SMS_RECEIVED".equals(intent.getAction()))return;String token=context.getSharedPreferences("dgm_sms",Context.MODE_PRIVATE).getString("token","");if(token.isEmpty())return;Bundle e=intent.getExtras();if(e==null)return;Object[] pdus=(Object[])e.get("pdus");if(pdus==null)return;String sender="";StringBuilder body=new StringBuilder();long ts=System.currentTimeMillis();for(Object p:pdus){SmsMessage m=SmsMessage.createFromPdu((byte[])p);if(m!=null){sender=m.getOriginatingAddress();body.append(m.getMessageBody());ts=m.getTimestampMillis();}}try{JSONObject o=new JSONObject();o.put("external_id","rx-"+ts+"-"+sender);o.put("direction","inbound");o.put("sender",sender==null?"":sender);o.put("body",body.toString());o.put("received_at",new java.util.Date(ts).toInstant().toString());String t=token,payload=o.toString();new Thread(()->MainActivityPost.post("/api/sms/ingest",t,payload)).start();}catch(Exception ignored){}}}